<script>
const EVENTS = __EVENTS__;
const POLICY = __POLICY__;

const HAND_LABEL = {left:"左手", right:"右手", both:"双手"};
const ACTION_LABEL = {
  pick_up:"取起 pick_up", transfer:"转交 transfer", adjust:"对位调整 adjust",
  fit:"插入/贴合 fit", fasten:"旋拧 fasten", flip:"翻面 flip", put_down:"放下 put_down", hold:"扶持 hold"
};
const OBJECT_LABEL = {
  body:"机体 body", shaft:"轴/转子 shaft", gear:"齿轮件 gear",
  adapter_plate:"适配件/环 adapter_plate", bearing_plate:"圆盘总成 bearing_plate",
  small_attachment:"小件 small_attachment", handle:"长柄 handle",
  screwdriver:"螺丝刀 screwdriver", wrench:"扳手 wrench", "null":"未知/未记录"
};
const ACTION_ORDER = ["pick_up","transfer","adjust","fit","fasten","flip","put_down","hold"];
const OBJECT_ORDER = ["body","shaft","gear","adapter_plate","bearing_plate","small_attachment","handle","screwdriver","wrench"];

function fmt(t){
  const m = Math.floor(t/60), s = t - m*60;
  return String(m).padStart(2,"0") + ":" + s.toFixed(1).padStart(4,"0");
}
function labelHand(h){ return HAND_LABEL[h] ? HAND_LABEL[h] + " " + h : h; }
function labelAction(a){ return ACTION_LABEL[a] || a; }
function labelObject(o){ const k = (o===null) ? "null" : o; return OBJECT_LABEL[k] || k; }

// Policy panel
(function(){
  const g = document.getElementById("policyGrid");
  function card(title, seg, extra){
    const hands = seg.hands.map(h=>`<span class="pill">${labelHand(h)}</span>`).join("");
    const acts = seg.actions.map(a=>`<span class="pill">${a}</span>`).join("");
    return `<div class="policy-card"><b>${title} · ${seg.start_s.toFixed(1)}–${seg.end_s.toFixed(1)} s</b>
      <div class="kv">手别：${hands}</div>
      <div class="kv" style="margin-top:4px">动作：${acts}</div>
      ${extra ? `<div class="kv" style="margin-top:6px">${extra}</div>` : ""}</div>`;
  }
  g.innerHTML =
    card("第一段 first", POLICY.first, "不记录 put_down / hold；双侧同时同类动作分成左右两条。") +
    card("第二段 second", POLICY.second, "在六类动作之外增加 put_down；hold 仍不记录。") +
    `<div class="policy-card"><b>全局字段</b>
      <div class="kv">record_holds：<span class="pill warn">${POLICY.record_holds}</span></div>
      <div class="kv" style="margin-top:4px">clock：<span class="pill">${POLICY.clock}</span></div>
      <div class="kv" style="margin-top:4px">bilateral_as_two_tracks：<span class="pill">${POLICY.bilateral_as_two_tracks}</span></div>
      <div class="kv" style="margin-top:6px">跨 83 秒动作按开始所在半段处理，不切成两次。</div>
    </div>`;
})();

// Populate filters
(function(){
  const fa = document.getElementById("f-action");
  ACTION_ORDER.forEach(a=>{
    if(EVENTS.some(e=>e.action===a)){
      const o=document.createElement("option"); o.value=a; o.textContent=labelAction(a); fa.appendChild(o);
    }
  });
  const fo = document.getElementById("f-object");
  OBJECT_ORDER.forEach(k=>{
    if(EVENTS.some(e=>(e.object===null?"null":e.object)===k)){
      const o=document.createElement("option"); o.value=k; o.textContent=labelObject(k==="null"?null:k); fo.appendChild(o);
    }
  });
  if(EVENTS.some(e=>e.object===null) && !fo.querySelector('"'option[value=\"null\"]')){
    const o=document.createElement(\"option\"); o.value=\"null\"; o.textContent=labelObject(null); fo.appendChild(o);
  }
})();

const tbody = document.getElementById(\"tbody\");
const empty = document.getElementById(\"empty\");
const countEl = document.getElementById(\"count\");
const fHand = document.getElementById(\"f-hand\");
const fAction = document.getElementById(\"f-action\");
const fObject = document.getElementById(\"f-object\");
const fText = document.getElementById(\"f-text\");

function matches(e){
  if(fHand.value "'!== "all" && e.hand !== fHand.value) return false;
  if(fAction.value !== "all" && e.action !== fAction.value) return false;
  if(fObject.value !== "all"){
    const k = (e.object===null) ? "null" : e.object;
    if(k !== fObject.value) return false;
  }
  const q = fText.value.trim().toLowerCase();
  if(q){
    const hay = [e.id,e.hand,e.action,e.object===null?"":e.object,e.note,fmt(e.start_s),fmt(e.end_s)].join(" ").toLowerCase();
    if(!hay.includes(q)) return false;
  }
  return true;
}

function rowFor(e){
  const tr = document.createElement("tr");
  tr.className = "event";
  tr.dataset.id = e.id;
  tr.innerHTML = `
    <td class="id">${e.id}</td>
    <td class="hand ${e.hand}">${labelHand(e.hand)}</td>
    <td class="time">${fmt(e.start_s)}–${fmt(e.end_s)}</td>
    <td class="action">${e.action}</td>
    <td class="obj">${labelObject(e.object)}</td>
    <td class="evidence">front + top</td>
    <td class="note">${e.note}</td>
    <td class="ops">
      <button class="small primary" data-act="play">播放</button>
      <button class="small" data-act="other">另一视角</button>
    </td>`;
  tr.addEventListener("click", ()=>selectEvent(e,true));
  tr.querySelector('"'[data-act=\"play\"]').addEventListener(\"click\", ev=>{ev.stopPropagation(); selectEvent(e,true);});
  tr.querySelector('[data-act=\"other\"]').addEventListener(\"click\", ev=>{ev.stopPropagation(); selectEvent(e,true); toggleCam();});
  return tr;
}

function render(){
  const list = EVENTS.filter(matches).sort((a,b)=>a.start_s-b.start_s || a.id.localeCompare(b.id));
  tbody.innerHTML = \"\";
  const frag = document.createDocumentFragment();
  list.forEach(e=>frag.appendChild(rowFor(e)));
  tbody.appendChild(frag);
  empty.style.display = list.length ? \"none\" : \"block\";
  countEl.textContent = "'`显示 ${list.length} / ${EVENTS.length} 条`;
  if(current && list.some(e=>e.id===current.id)){
    const tr = tbody.querySelector(`tr[data-id="${current.id}"]`);
    if(tr) tr.classList.add("selected");
  }
}
[fHand,fAction,fObject].forEach(el=>el.addEventListener("change",render));
fText.addEventListener("input",render);

const player = document.getElementById("player");
const playerTitle = document.getElementById("player-title");
const playerMeta = document.getElementById("player-meta");
const camLabel = document.getElementById("cam-label");
const switchBtn = document.getElementById("switch-cam");
const CAM_SRC = {front:"../input/front.mp4", top:"../input/top.mp4"};
let current = null;
let currentCam = "front";
let segmentActive = false;

function setSrc(cam){
  if(player.dataset.src === CAM_SRC[cam]) return;
  player.dataset.src = CAM_SRC[cam];
  player.src = CAM_SRC[cam];
  player.load();
}
function whenReady(fn){
  if(player.readyState >= 1) fn();
  else player.addEventListener("loadedmetadata", fn, {once:true});
}
function updateCamUI(){
  camLabel.textContent = currentCam === "front" ? "主时钟：front" : "当前视角：top（主时钟仍为 front）";
  switchBtn.textContent = currentCam === "front" ? "切换视角：top" : "切换视角：front";
}
function selectEvent(e, autoplay){
  current = e;
  segmentActive = true;
  document.querySelectorAll("tr.event").forEach(r=>r.classList.toggle("selected", r.dataset.id===e.id));
  playerTitle.textContent = `${e.id} · ${labelHand(e.hand)} · ${e.action} · ${labelObject(e.object)}`;
  playerMeta.textContent = `${fmt(e.start_s)}–${fmt(e.end_s)}（${currentCam}）`;
  const playNow = ()=>{
    player.currentTime = e.start_s;
    if(autoplay) player.play().catch(()=>{});
  };
  setSrc(currentCam);
  whenReady(playNow);
}
function playSegment(){
  if(!current) return;
  segmentActive = true;
  setSrc(currentCam);
  whenReady(()=>{
    player.currentTime = current.start_s;
    player.play().catch(()=>{});
  });
}
function toggleCam(){
  if(!current) return;
  const t = player.currentTime;
  const wasPlaying = !player.paused;
  currentCam = currentCam === "front" ? "top" : "front";
  setSrc(currentCam);
  updateCamUI();
  playerMeta.textContent = `${fmt(current.start_s)}–${fmt(current.end_s)}（${currentCam}）`;
  whenReady(()=>{
    const lo = current.start_s, hi = current.end_s;
    player.currentTime = Math.min(Math.max(t || lo, lo), hi);
    if(wasPlaying) player.play().catch(()=>{});
  });
}
document.getElementById("play-seg").addEventListener("click", playSegment);
switchBtn.addEventListener("click", toggleCam);
document.getElementById("clear-seg").addEventListener("click", ()=>{
  current = null; segmentActive = false;
  player.pause();
  playerTitle.textContent = "未选择片段";
  playerMeta.textContent = "点击表格中的“播放”或整行选择事件";
  document.querySelectorAll("tr.event").forEach(r=>r.classList.remove("selected"));
});
player.addEventListener("timeupdate", ()=>{
  if(segmentActive && current && !player.paused && player.currentTime >= current.end_s - 0.03){
    player.pause();
    player.currentTime = current.end_s;
    segmentActive = false;
    playerMeta.textContent = `${fmt(current.start_s)}–${fmt(current.end_s)}（已到片段终点）`;
  }
});

updateCamUI();
render();

// Consistency check against actions.json when the page is served over HTTP.
fetch("actions.json").then(r=>r.ok?r.json():Promise.reject()).then(d=>{
  const el = document.getElementById("verify");
  if(Array.isArray(d.events) && d.events.length === EVENTS.length){
    el.innerHTML = `<span class="status-ok">校验通过：页面内嵌 ${EVENTS.length} 条事件，与 actions.json 条数一致。</span>`;
  }else{
    el.innerHTML = `<span class="status-bad">校验失败：页面 ${EVENTS.length} 条，actions.json ${d.events ? d.events.length : "?"} 条。</span>`;
  }
}).catch(()=>{
  document.getElementById("verify").textContent = `页面内嵌 ${EVENTS.length} 条事件；直接以文件方式打开时浏览器可能禁止读取 actions.json，可用本地静态服务器复核。`;
});
</script>
</body>
</html>
