  "clock": "front",
  "bilateral_as_two_tracks": true
};

const HAND_LABEL = {left:"左手", right:"右手", both:"双手"};
const ACTION_LABEL = {
  pick_up:"取起 pick_up", transfer:"转交 transfer", adjust:"对位调整 adjust",
  fit:"插入/贴合 fit", fasten:"旋拧 fasten", flip:"翻面 flip", put_down:"放下 put_down", hold:"扶持 hold"
};
const OBJECT_LABEL = {
  body:"机体 body", shaft:"轴/转子 shaft", gear:"齿轮件 gear",
  adapter_plate:"适配件/环 adapter_plate", bearing_plate:"圆盘总成 bearing_plate",
  small_attachment:"小件 small_attachment", handle:"长柄 handle",
  screwdriver:"螺丝刀 screwdriver", wrench:"扳手 wrench", "null":"未知/未记录"
};
const ACTION_ORDER = ["pick_up","transfer","adjust","fit","fasten","flip","put_down","hold"];
const OBJECT_ORDER = ["body","shaft","gear","adapter_plate","bearing_plate","small_attachment","handle","screwdriver","wrench"];

function fmt(t){
  const m = Math.floor(t/60), s = t - m*60;
  return String(m).padStart(2,"0") + ":" + s.toFixed(1).padStart(4,"0");
}
function labelHand(h){ return HAND_LABEL[h] ? HAND_LABEL[h] + " " + h : h; }
function labelAction(a){ return ACTION_LABEL[a] || a; }
function labelObject(o){ const k = (o===null) ? "null" : o; return OBJECT_LABEL[k] || k; }

// Policy panel
(function(){
  const g = document.getElementById("policyGrid");
  function card(title, seg, extra){
    const hands = seg.hands.map(h=>`<span class="pill">${labelHand(h)}</span>`).join("");
    const acts = seg.actions.map(a=>`<span class="pill">${a}</span>`).join("");
    return `<div class="policy-card"><b>${title} · ${seg.start_s.toFixed(1)}–${seg.end_s.toFixed(1)} s</b>
      <div class="kv">手别：${hands}</div>
      <div class="kv" style="margin-top:4px">动作：${acts}</div>
      ${extra ? `<div class="kv" style="margin-top:6px">${extra}</div>` : ""}</div>`;
  }
  g.innerHTML =
    card("第一段 first", POLICY.first, "不记录 put_down / hold；双侧同时同类动作分成左右两条。") +
    card("第二段 second", POLICY.second, "在六类动作之外增加 put_down；hold 仍不记录。") +
    `<div class="policy-card"><b>全局字段</b>
      <div class="kv">record_holds：<span class="pill warn">${POLICY.record_holds}</span></div>
      <div class="kv" style="margin-top:4px">clock：<span class="pill">${POLICY.clock}</span></div>
      <div class="kv" style="margin-top:4px">bilateral_as_two_tracks：<span class="pill">${POLICY.bilateral_as_two_tracks}</span></div>
      <div class="kv" style="margin-top:6px">跨 83 秒动作按开始所在半段处理，不切成两次。</div>
    </div>`;
})();

// Populate filters
(function(){
