    if(EVENTS.some(e=>e.action===a)){
      const o=document.createElement("option"); o.value=a; o.textContent=labelAction(a); fa.appendChild(o);
    }
  });
  const fo = document.getElementById("f-object");
  OBJECT_ORDER.forEach(k=>{
    if(EVENTS.some(e=>(e.object===null?"null":e.object)===k)){
      const o=document.createElement("option"); o.value=k; o.textContent=labelObject(k==="null"?null:k); fo.appendChild(o);
    }
  });
  if(EVENTS.some(e=>e.object===null) && !fo.querySelector('option[value="null"]')){
    const o=document.createElement("option"); o.value="null"; o.textContent=labelObject(null); fo.appendChild(o);
  }
})();

const tbody = document.getElementById("tbody");
const empty = document.getElementById("empty");
const countEl = document.getElementById("count");
const fHand = document.getElementById("f-hand");
const fAction = document.getElementById("f-action");
const fObject = document.getElementById("f-object");
const fText = document.getElementById("f-text");

function matches(e){
  if(fHand.value !== "all" && e.hand !== fHand.value) return false;
  if(fAction.value !== "all" && e.action !== fAction.value) return false;
  if(fObject.value !== "all"){
    const k = (e.object===null) ? "null" : e.object;
    if(k !== fObject.value) return false;
  }
  const q = fText.value.trim().toLowerCase();
  if(q){
    const hay = [e.id,e.hand,e.action,e.object===null?"":e.object,e.note,fmt(e.start_s),fmt(e.end_s)].join(" ").toLowerCase();
    if(!hay.includes(q)) return false;
  }
  return true;
}

function rowFor(e){
  const tr = document.createElement("tr");
  tr.className = "event";
  tr.dataset.id = e.id;
  tr.innerHTML = `
    <td class="id">${e.id}</td>
    <td class="hand ${e.hand}">${labelHand(e.hand)}</td>
    <td class="time">${fmt(e.start_s)}–${fmt(e.end_s)}</td>
    <td class="action">${e.action}</td>
    <td class="obj">${labelObject(e.object)}</td>
    <td class="evidence">front + top</td>
    <td class="note">${e.note}</td>
    <td class="ops">
      <button class="small primary" data-act="play">播放</button>
      <button class="small" data-act="other">另一视角</button>
    </td>`;
  tr.addEventListener("click", ()=>selectEvent(e,true));
  tr.querySelector('[data-act="play"]').addEventListener("click", ev=>{ev.stopPropagation(); selectEvent(e,true);});
  tr.querySelector('[data-act="other"]').addEventListener("click", ev=>{ev.stopPropagation(); selectEvent(e,true); toggleCam();});
  return tr;
}

function render(){
  const list = EVENTS.filter(matches).sort((a,b)=>a.start_s-b.start_s || a.id.localeCompare(b.id));
  tbody.innerHTML = "";
  const frag = document.createDocumentFragment();
  list.forEach(e=>frag.appendChild(rowFor(e)));
  tbody.appendChild(frag);
  empty.style.display = list.length ? "none" : "block";
  countEl.textContent = `显示 ${list.length} / ${EVENTS.length} 条`;
  if(current && list.some(e=>e.id===current.id)){
    const tr = tbody.querySelector(`tr[data-id="${current.id}"]`);
    if(tr) tr.classList.add("selected");
  }
}
[fHand,fAction,fObject].forEach(el=>el.addEventListener("change",render));
fText.addEventListener("input",render);

